1	// Command ledger 是本地器具校准台账的命令行入口。
2	//
3	// 用法：
4	//
5	//	ledger -f 台账文件.json <子命令> [参数]
6	//
7	// 数据只保存在 -f 指定的本机文件中；不指定时使用当前目录下的 ledger.json。
8	// 不同文件是互不混入的不同台账，退出后再次打开同一文件可继续查询和操作。
9	package main
10	
11	import (
12		"encoding/json"
13		"errors"
14		"flag"
15		"fmt"
16		"io"
17		"math"
18		"os"
19		"strconv"
20		"strings"
21	
22		"github.com/bengzyyys/calibration-ledger/calibrate"
23	)
24	
25	const usageText = `本地器具校准台账（仅本机，不连接真实实验室）
26	
27	用法：
28	  ledger -f <台账文件> [--json] <子命令> [参数]
29	
30	子命令：
31	  register   登记器具：--id 编号 --name 名称 --allowed 允许绝对误差
32	  status     切换状态：--id 编号 --status 在用|停用|待校准
33	  cert       录入证书：--instrument 器具编号 --number 证书编号 \
34	             --cal-date YYYY-MM-DD --expiry YYYY-MM-DD \
35	             --method 方法 --error 测得误差 --summary 摘要
36	  use        申请使用器具：--id 编号（允许与拒绝都会留痕）
37	  review     按器具核对：--id 编号
38	  list       列出全部登记器具
39	  plan       建立校准计划：--instrument 器具编号 --number 计划编号 \
40	             --date YYYY-MM-DD --note 非空说明
41	  reschedule 计划改期：--number 计划编号 --date 新日期 --reason 非空原因
42	  cancel     取消计划：--number 计划编号 --reason 非空原因
43	  complete   用证书完成计划：--number 计划编号 --certificate 证书编号
44	  todos      校准待办：[--instrument 器具编号]（默认全部未结束计划）
45	
46	通用参数：
47	  -f, --file   台账文件路径（默认 ledger.json）
48	      --json   以 JSON 输出结果
49	
50	退出码：0 成功；1 业务拒绝或未找到；2 参数或读写错误。
51	`
52	
53	// options 是所有子命令共用的全局参数。
54	type options struct {
55		file   string
56		asJSON bool
57	}
58	
59	func main() {
60		os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
61	}
62	
63	func run(args []string, stdout, stderr io.Writer) int {
64		if len(args) == 0 {
65			fmt.Fprint(stderr, usageText)
66			return 2
67		}
68		var opts options
69		fileSet := false
70		cmd := ""
71		businessArgs := make([]string, 0, len(args))
72		// 全局参数（-f/--file、--json）既可以写在子命令前，也可以与器具编号、
73		// 证书编号等业务参数交错写在子命令之后。这里先从左到右扫描整条命令行，
74		// 剥除全局参数并确定最终台账路径，再打开该文件：因此 -f 出现的位置不会
75		// 改变它选中的台账；同一次调用出现多个文件参数时，短名与长名共同参与
76		// 从左到右的顺序，以最后一次明确给出的路径为准。
77		for i := 0; i < len(args); i++ {
78			a := args[i]
79			if cmd == "" && !strings.HasPrefix(a, "-") {
80				// 第一个不以“-”开头的参数是子命令；其后的位置参数仍要继续扫描。
81				cmd = a
82				continue
83			}
84			switch {
85			case a == "-f" || a == "--file" || a == "-file":
86				if i+1 >= len(args) {
87					fmt.Fprintf(stderr, "%s 需要一个值\n", a)
88					return 2
89				}
90				i++
91				opts.file = args[i]
92				fileSet = true
93			case strings.HasPrefix(a, "--file="):
94				opts.file = a[len("--file="):]
95				fileSet = true
96			case strings.HasPrefix(a, "-file="):
97				opts.file = a[len("-file="):]
98				fileSet = true
99			case strings.HasPrefix(a, "-f="):
100				opts.file = strings.TrimPrefix(a, "-f=")
101				fileSet = true
102			case strings.HasPrefix(a, "-f") && len(a) > 2:
103				opts.file = a[2:]
104				fileSet = true
105			case a == "--json" || a == "-json":
106				opts.asJSON = true
107			case a == "--" && cmd != "":
108				// “--” 终止后续标志解析：其后的参数原样交给子命令
109				// （与此前 flag 包的行为一致），即使其中出现 -f 也不再视为全局参数。
110				businessArgs = append(businessArgs, args[i:]...)
111				i = len(args)
112			default:
113				if cmd == "" {
114					fmt.Fprintf(stderr, "未知全局参数 %s\n\n%s", a, usageText)
115					return 2
116				}
117				businessArgs = append(businessArgs, a)
118			}
119		}
120		if fileSet {
121			if strings.TrimSpace(opts.file) == "" {
122				fmt.Fprintln(stderr, "台账文件路径不能为空或只有空白")
123				return 2
124			}
125		} else {
126			opts.file = "ledger.json"
127		}
128		if cmd == "" {
129			fmt.Fprint(stderr, usageText)
130			return 2
131		}
132		cmdArgs := businessArgs
133		if cmd == "help" || cmd == "-h" || cmd == "--help" {
134			fmt.Fprint(stdout, usageText)
135			return 0
136		}
137	
138		// 最终路径确定之后才打开台账：被后续 -f 覆盖掉的旧路径与默认文件
139		// 即使损坏或不可读，也不会影响对有效目标文件的操作。
140		l, err := calibrate.Open(opts.file)
141		if err != nil {
142			fmt.Fprintln(stderr, "打开台账失败：", err)
143			return 2
144		}
145	
146		switch cmd {
147		case "register":
148			return cmdRegister(l, cmdArgs, opts, stdout, stderr)
149		case "status":
150			return cmdStatus(l, cmdArgs, opts, stdout, stderr)
151		case "cert":
152			return cmdCert(l, cmdArgs, opts, stdout, stderr)
153		case "use":
154			return cmdUse(l, cmdArgs, opts, stdout, stderr)
155		case "review":
156			return cmdReview(l, cmdArgs, opts, stdout, stderr)
157		case "list":
158			return cmdList(l, cmdArgs, opts, stdout, stderr)
159		case "plan":
160			return cmdPlan(l, cmdArgs, opts, stdout, stderr)
161		case "reschedule":
162			return cmdReschedule(l, cmdArgs, opts, stdout, stderr)
163		case "cancel":
164			return cmdCancel(l, cmdArgs, opts, stdout, stderr)
165		case "complete":
166			return cmdComplete(l, cmdArgs, opts, stdout, stderr)
167		case "todos":
168			return cmdTodos(l, cmdArgs, opts, stdout, stderr)
169		default:
170			fmt.Fprintf(stderr, "未知子命令 %q\n\n%s", cmd, usageText)
171			return 2
172		}
173	}
174	
175	// newFlagSet 构造子命令自己的标志集。台账文件与 --json 已在打开台账前
176	// 从整条命令行统一解析，这里只保留 --json 的登记，绝不在此处重新登记
177	// -f/--file：否则子命令后的文件参数会指向与已打开台账不同的路径。
178	func newFlagSet(name string, opts *options) *flag.FlagSet {
179		fs := flag.NewFlagSet(name, flag.ContinueOnError)
180		fs.SetOutput(io.Discard)
181		fs.BoolVar(&opts.asJSON, "json", opts.asJSON, "以 JSON 输出")
182		return fs
183	}
184	
185	func parseFloat(stderr io.Writer, raw, field string) (float64, bool) {
186		v, err := strconv.ParseFloat(strings.TrimSpace(raw), 64)
187		if err != nil || math.IsNaN(v) || math.IsInf(v, 0) {
188			fmt.Fprintf(stderr, "%s 必须是有限数字\n", field)
189			return 0, false
190		}
191		return v, true
192	}
193	
194	func emit(opts options, stdout, stderr io.Writer, human string, v any) int {
195		if opts.asJSON {
196			raw, err := json.MarshalIndent(v, "", "  ")
197			if err != nil {
198				fmt.Fprintln(stderr, "输出 JSON 失败：", err)
199				return 2
200			}
201			fmt.Fprintln(stdout, string(raw))
202			return 0
203		}
204		fmt.Fprint(stdout, human)
205		return 0
206	}
207	
208	// failBusiness 处理业务拒绝：退出码 1，原记录未被改动。
209	func failBusiness(opts options, stdout, stderr io.Writer, err error, rejected any) int {
210		if opts.asJSON {
211			raw, _ := json.MarshalIndent(rejected, "", "  ")
212			fmt.Fprintln(stdout, string(raw))
213		}
214		fmt.Fprintln(stderr, "已拒绝：", err)
215		return 1
216	}
217	
218	func failIO(stderr io.Writer, err error) int {
219		fmt.Fprintln(stderr, "操作失败：", err)
220		return 2
221	}
222	
223	func cmdRegister(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
224		fs := newFlagSet("register", &opts)
225		id := fs.String("id", "", "器具唯一编号")
226		name := fs.String("name", "", "器具名称")
227		allowed := fs.String("allowed", "", "允许的绝对误差（不小于零的有限数）")
228		if err := fs.Parse(args); err != nil {
229			fmt.Fprintln(stderr, "register 参数错误：", err)
230			return 2
231		}
232		if *id == "" || *name == "" || *allowed == "" {
233			fmt.Fprintln(stderr, "register 必须提供 --id、--name、--allowed")
234			return 2
235		}
236		allowedErr, ok := parseFloat(stderr, *allowed, "允许的绝对误差")
237		if !ok {
238			return 2
239		}
240		inst, err := l.Register(calibrate.RegisterInput{
241			ID: *id, Name: *name, AllowedError: allowedErr,
242		})
243		if err != nil {
244			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
245				return failBusiness(opts, stdout, stderr, err,
246					map[string]any{"accepted": false, "error": err.Error()})
247			}
248			return failIO(stderr, err)
249		}
250		human := fmt.Sprintf("已登记器具 %s（%s），允许绝对误差 %g，状态：%s\n",
251			inst.ID, inst.Name, inst.AllowedError, inst.Status)
252		return emit(opts, stdout, stderr, human, map[string]any{"accepted": true, "instrument": inst})
253	}
254	
255	func cmdStatus(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
256		fs := newFlagSet("status", &opts)
257		id := fs.String("id", "", "器具编号")
258		status := fs.String("status", "", "在用|停用|待校准")
259		if err := fs.Parse(args); err != nil {
260			fmt.Fprintln(stderr, "status 参数错误：", err)
261			return 2
262		}
263		if *id == "" || *status == "" {
264			fmt.Fprintln(stderr, "status 必须提供 --id、--status")
265			return 2
266		}
267		st, err := calibrate.ParseStatus(*status)
268		if err != nil {
269			fmt.Fprintln(stderr, err)
270			return 2
271		}
272		if err := l.SetStatus(*id, st); err != nil {
273			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
274				return failBusiness(opts, stdout, stderr, err,
275					map[string]any{"accepted": false, "error": err.Error()})
276			}
277			return failIO(stderr, err)
278		}
279		human := fmt.Sprintf("器具 %s 已切换为%s\n", *id, st)
280		return emit(opts, stdout, stderr, human,
281			map[string]any{"accepted": true, "id": *id, "status": st})
282	}
283	
284	func cmdCert(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
285		fs := newFlagSet("cert", &opts)
286		instrument := fs.String("instrument", "", "器具编号")
287		number := fs.String("number", "", "证书编号（全台账唯一）")
288		calDate := fs.String("cal-date", "", "校准日期 YYYY-MM-DD")
289		expiry := fs.String("expiry", "", "有效期截止日 YYYY-MM-DD")
290		method := fs.String("method", "", "校准方法")
291		measured := fs.String("error", "", "测得误差（有限数）")
292		summary := fs.String("summary", "", "证书摘要")
293		if err := fs.Parse(args); err != nil {
294			fmt.Fprintln(stderr, "cert 参数错误：", err)
295			return 2
296		}
297		missing := []string{}
298		for k, v := range map[string]string{
299			"--instrument": *instrument, "--number": *number, "--cal-date": *calDate,
300			"--expiry": *expiry, "--method": *method, "--error": *measured, "--summary": *summary,
301		} {
302			if strings.TrimSpace(v) == "" {
303				missing = append(missing, k)
304			}
305		}
306		if len(missing) > 0 {
307			fmt.Fprintln(stderr, "cert 缺少必填参数：", strings.Join(missing, "、"))
308			return 2
309		}
310		measuredErr, ok := parseFloat(stderr, *measured, "测得误差")
311		if !ok {
312			return 2
313		}
314		cert, duplicate, err := l.AddCertificate(calibrate.CertificateInput{
315			InstrumentID: *instrument,
316			Number:       *number,
317			CalDate:      *calDate,
318			Expiry:       *expiry,
319			Method:       *method,
320			Error:        measuredErr,
321			Summary:      *summary,
322		})
323		if err != nil {
324			if calibrate.IsValidation(err) || calibrate.IsConflict(err) || errors.Is(err, calibrate.ErrNotFound) {
325				return failBusiness(opts, stdout, stderr, err,
326					map[string]any{"accepted": false, "conflict": calibrate.IsConflict(err), "error": err.Error()})
327			}
328			return failIO(stderr, err)
329		}
330		note := "已录入新证书"
331		if duplicate {
332			note = "同号证书且内容一致，返回原证书，未增加历史记录"
333		}
334		verdict := "合格"
335		if math.Abs(cert.Error) > allowedErrorOf(l, cert.InstrumentID) {
336			verdict = "超差"
337		}
338		human := fmt.Sprintf("%s：%s（器具 %s，校准日期 %s，截止日 %s，测得误差 %g，判定：%s）\n",
339			note, cert.Number, cert.InstrumentID, cert.CalDate, cert.Expiry, cert.Error, verdict)
340		return emit(opts, stdout, stderr, human,
341			map[string]any{"accepted": true, "duplicate": duplicate, "verdict": verdict, "certificate": cert})
342	}
343	
344	func allowedErrorOf(l *calibrate.Ledger, id string) float64 {
345		r, err := l.Review(id)
346		if err != nil {
347			return 0
348		}
349		return r.Instrument.AllowedError
350	}
351	
352	func cmdUse(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
353		fs := newFlagSet("use", &opts)
354		id := fs.String("id", "", "器具编号")
355		if err := fs.Parse(args); err != nil {
356			fmt.Fprintln(stderr, "use 参数错误：", err)
357			return 2
358		}
359		if strings.TrimSpace(*id) == "" {
360			fmt.Fprintln(stderr, "use 必须提供 --id")
361			return 2
362		}
363		d, err := l.RequestUse(*id)
364		if err != nil {
365			if errors.Is(err, calibrate.ErrNotFound) || calibrate.IsValidation(err) {
366				return failBusiness(opts, stdout, stderr, err,
367					map[string]any{"accepted": false, "recorded": false, "error": err.Error()})
368			}
369			return failIO(stderr, err)
370		}
371		if !d.Allowed {
372			var sb strings.Builder
373			sb.WriteString(fmt.Sprintf("拒绝使用器具 %s，已记录本次拒绝及原因：\n", *id))
374			for _, r := range d.Reasons {
375				sb.WriteString("  - " + r + "\n")
376			}
377			if opts.asJSON {
378				raw, _ := json.MarshalIndent(map[string]any{
379					"allowed": false, "recorded": true, "decision": d,
380				}, "", "  ")
381				fmt.Fprintln(stdout, string(raw))
382			}
383			fmt.Fprint(stderr, sb.String())
384			return 1
385		}
386		human := fmt.Sprintf("允许使用器具 %s，已记录本次申请。\n", *id)
387		return emit(opts, stdout, stderr, human,
388			map[string]any{"allowed": true, "recorded": true, "decision": d})
389	}
390	
391	func cmdReview(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
392		fs := newFlagSet("review", &opts)
393		id := fs.String("id", "", "器具编号")
394		if err := fs.Parse(args); err != nil {
395			fmt.Fprintln(stderr, "review 参数错误：", err)
396			return 2
397		}
398		if strings.TrimSpace(*id) == "" {
399			fmt.Fprintln(stderr, "review 必须提供 --id")
400			return 2
401		}
402		r, err := l.Review(*id)
403		if err != nil {
404			if errors.Is(err, calibrate.ErrNotFound) {
405				return failBusiness(opts, stdout, stderr, err,
406					map[string]any{"found": false, "error": err.Error()})
407			}
408			return failIO(stderr, err)
409		}
410		var sb strings.Builder
411		fmt.Fprintf(&sb, "器具 %s（%s）\n", r.Instrument.ID, r.Instrument.Name)
412		fmt.Fprintf(&sb, "  允许绝对误差：%g；当前状态：%s\n", r.Instrument.AllowedError, r.Instrument.Status)
413		if r.CanUse {
414			sb.WriteString("  当前能否使用：可以\n")
415		} else {
416			sb.WriteString("  当前能否使用：不可以，原因：\n")
417			for _, reason := range r.Reasons {
418				sb.WriteString("    - " + reason + "\n")
419			}
420		}
421		if r.Latest == nil {
422			sb.WriteString("  最近证书：无\n")
423		} else {
424			fmt.Fprintf(&sb, "  最近证书：%s（校准日期 %s，截止日 %s，判定：%s，%s）\n",
425				r.Latest.Number, r.Latest.CalDate, r.Latest.Expiry,
426				verdictText(r.Latest.Pass), expiryText(r.Latest.Expired))
427		}
428		if len(r.History) == 0 {
429			sb.WriteString("  历史证书：无\n")
430		} else {
431			sb.WriteString("  历史证书（按校准日期由近到远）：\n")
432			for _, c := range r.History {
433				fmt.Fprintf(&sb, "    - %s %s 截止 %s 误差 %g %s %s（%s）\n",
434					c.Number, c.CalDate, c.Expiry, c.Error,
435					verdictText(c.Pass), expiryText(c.Expired), c.Method)
436			}
437		}
438		if len(r.Rejections) == 0 {
439			sb.WriteString("  被拒绝的使用记录：无\n")
440		} else {
441			sb.WriteString("  被拒绝的使用记录（原因为申请当时冻结）：\n")
442			for _, u := range r.Rejections {
443				sb.WriteString("    - " + u.RequestedAt + "\n")
444				for _, reason := range u.Reasons {
445					sb.WriteString("        - " + reason + "\n")
446				}
447			}
448		}
449		if len(r.Plans) == 0 {
450			sb.WriteString("  校准计划：无\n")
451		} else {
452			sb.WriteString("  校准计划（含当前及已结束计划、改期记录与关联证书）：\n")
453			for _, p := range r.Plans {
454				head := fmt.Sprintf("    - %s %s 状态：%s", p.Number, p.PlannedDate, p.Status)
455				if p.Open() {
456					head += "（" + p.Marker + "）"
457				}
458				if p.OriginalDate != p.PlannedDate {
459					head += fmt.Sprintf("，最初计划日期 %s", p.OriginalDate)
460				}
461				head += "，说明：" + p.Note + "\n"
462				sb.WriteString(head)
463				for _, ch := range p.Changes {
464					fmt.Fprintf(&sb, "        改期 %s → %s（%s），原因：%s\n",
465						ch.From, ch.To, ch.ChangedAt, ch.Reason)
466				}
467				if p.Status == calibrate.PlanStatusCanceled {
468					fmt.Fprintf(&sb, "        取消于 %s，原因：%s\n", p.CanceledAt, p.CancelReason)
469				}
470				if p.Status == calibrate.PlanStatusDone {
471					fmt.Fprintf(&sb, "        完成于 %s，证书 %s\n", p.CompletedAt, p.CertificateNumber)
472				}
473			}
474		}
475		return emit(opts, stdout, stderr, sb.String(), r)
476	}
477	
478	func verdictText(pass bool) string {
479		if pass {
480			return "合格"
481		}
482		return "超差"
483	}
484	
485	func expiryText(expired bool) string {
486		if expired {
487			return "已到期"
488		}
489		return "未到期"
490	}
491	
492	func cmdList(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
493		fs := newFlagSet("list", &opts)
494		if err := fs.Parse(args); err != nil {
495			fmt.Fprintln(stderr, "list 参数错误：", err)
496			return 2
497		}
498		instruments := l.Instruments()
499		var sb strings.Builder
500		if len(instruments) == 0 {
501			sb.WriteString("台账中还没有器具。\n")
502		}
503		for _, in := range instruments {
504			fmt.Fprintf(&sb, "%s\t%s\t允许误差 %g\t%s\n", in.ID, in.Name, in.AllowedError, in.Status)
505		}
506		return emit(opts, stdout, stderr, sb.String(),
507			map[string]any{"instruments": instruments, "count": len(instruments)})
508	}
509	
510	// failPlanBusiness 是计划类命令共用的业务拒绝输出（退出码 1）。
511	func failPlanBusiness(opts options, stdout, stderr io.Writer, err error, extra map[string]any) int {
512		resp := map[string]any{"accepted": false, "error": err.Error()}
513		for k, v := range extra {
514			resp[k] = v
515		}
516		return failBusiness(opts, stdout, stderr, err, resp)
517	}
518	
519	func cmdPlan(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
520		fs := newFlagSet("plan", &opts)
521		instrument := fs.String("instrument", "", "器具编号")
522		number := fs.String("number", "", "计划编号（全台账唯一，不可复用）")
523		date := fs.String("date", "", "计划日期 YYYY-MM-DD（不早于今天）")
524		note := fs.String("note", "", "非空计划说明")
525		if err := fs.Parse(args); err != nil {
526			fmt.Fprintln(stderr, "plan 参数错误：", err)
527			return 2
528		}
529		missing := []string{}
530		for k, v := range map[string]string{
531			"--instrument": *instrument, "--number": *number, "--date": *date, "--note": *note,
532		} {
533			if strings.TrimSpace(v) == "" {
534				missing = append(missing, k)
535			}
536		}
537		if len(missing) > 0 {
538			fmt.Fprintln(stderr, "plan 缺少必填参数：", strings.Join(missing, "、"))
539			return 2
540		}
541		p, err := l.CreatePlan(calibrate.PlanInput{
542			Number: *number, InstrumentID: *instrument, Date: *date, Note: *note,
543		})
544		if err != nil {
545			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
546				return failPlanBusiness(opts, stdout, stderr, err, nil)
547			}
548			return failIO(stderr, err)
549		}
550		human := fmt.Sprintf("已为器具 %s 建立校准计划 %s，计划日期 %s，说明：%s\n",
551			p.InstrumentID, p.Number, p.PlannedDate, p.Note)
552		return emit(opts, stdout, stderr, human, map[string]any{"accepted": true, "plan": p})
553	}
554	
555	func cmdReschedule(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
556		fs := newFlagSet("reschedule", &opts)
557		number := fs.String("number", "", "计划编号")
558		date := fs.String("date", "", "新计划日期 YYYY-MM-DD（不早于今天）")
559		reason := fs.String("reason", "", "非空改期原因")
560		if err := fs.Parse(args); err != nil {
561			fmt.Fprintln(stderr, "reschedule 参数错误：", err)
562			return 2
563		}
564		missing := []string{}
565		for k, v := range map[string]string{
566			"--number": *number, "--date": *date, "--reason": *reason,
567		} {
568			if strings.TrimSpace(v) == "" {
569				missing = append(missing, k)
570			}
571		}
572		if len(missing) > 0 {
573			fmt.Fprintln(stderr, "reschedule 缺少必填参数：", strings.Join(missing, "、"))
574			return 2
575		}
576		p, err := l.ReschedulePlan(*number, *date, *reason)
577		if err != nil {
578			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
579				return failPlanBusiness(opts, stdout, stderr, err, nil)
580			}
581			return failIO(stderr, err)
582		}
583		human := fmt.Sprintf("计划 %s 已改期为 %s（第 %d 次改期）。\n",
584			p.Number, p.PlannedDate, len(p.Changes))
585		return emit(opts, stdout, stderr, human, map[string]any{"accepted": true, "plan": p})
586	}
587	
588	func cmdCancel(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
589		fs := newFlagSet("cancel", &opts)
590		number := fs.String("number", "", "计划编号")
591		reason := fs.String("reason", "", "非空取消原因")
592		if err := fs.Parse(args); err != nil {
593			fmt.Fprintln(stderr, "cancel 参数错误：", err)
594			return 2
595		}
596		if strings.TrimSpace(*number) == "" || strings.TrimSpace(*reason) == "" {
597			fmt.Fprintln(stderr, "cancel 必须提供 --number、--reason")
598			return 2
599		}
600		p, err := l.CancelPlan(*number, *reason)
601		if err != nil {
602			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
603				return failPlanBusiness(opts, stdout, stderr, err, nil)
604			}
605			return failIO(stderr, err)
606		}
607		human := fmt.Sprintf("计划 %s 已于 %s 取消，原因：%s；不再列入待办。\n",
608			p.Number, p.CanceledAt, p.CancelReason)
609		return emit(opts, stdout, stderr, human, map[string]any{"accepted": true, "plan": p})
610	}
611	
612	func cmdComplete(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
613		fs := newFlagSet("complete", &opts)
614		number := fs.String("number", "", "计划编号")
615		certificate := fs.String("certificate", "", "证书编号")
616		if err := fs.Parse(args); err != nil {
617			fmt.Fprintln(stderr, "complete 参数错误：", err)
618			return 2
619		}
620		if strings.TrimSpace(*number) == "" || strings.TrimSpace(*certificate) == "" {
621			fmt.Fprintln(stderr, "complete 必须提供 --number、--certificate")
622			return 2
623		}
624		p, idempotent, err := l.CompletePlan(*number, *certificate)
625		if err != nil {
626			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
627				return failPlanBusiness(opts, stdout, stderr, err, nil)
628			}
629			return failIO(stderr, err)
630		}
631		note := "已完成"
632		if idempotent {
633			note = "该计划已由此证书完成，返回原结果，未刷新完成时间"
634		}
635		human := fmt.Sprintf("%s：计划 %s，证书 %s，完成时间 %s。\n",
636			note, p.Number, p.CertificateNumber, p.CompletedAt)
637		return emit(opts, stdout, stderr, human,
638			map[string]any{"accepted": true, "idempotent": idempotent, "plan": p})
639	}
640	
641	func cmdTodos(l *calibrate.Ledger, args []string, opts options, stdout, stderr io.Writer) int {
642		fs := newFlagSet("todos", &opts)
643		instrument := fs.String("instrument", "", "只看该器具编号的待办")
644		if err := fs.Parse(args); err != nil {
645			fmt.Fprintln(stderr, "todos 参数错误：", err)
646			return 2
647		}
648		items, err := l.Todos(*instrument)
649		if err != nil {
650			if errors.Is(err, calibrate.ErrNotFound) {
651				return failBusiness(opts, stdout, stderr, err,
652					map[string]any{"found": false, "error": err.Error()})
653			}
654			return failIO(stderr, err)
655		}
656		var sb strings.Builder
657		if len(items) == 0 {
658			sb.WriteString("无待办。\n")
659		}
