662				it.PlanNumber, it.InstrumentID, it.InstrumentName, it.Status,
663				it.PlannedDate, it.Marker, it.Note)
664		}
665		return emit(opts, stdout, stderr, sb.String(),
666			map[string]any{"todos": items, "count": len(items)})
667	}
